const items = $input.all();
const targets = ["vol_10411","vol_10755","vol_10390","vol_10467","vol_10340","vol_10394","vol_10422","vol_10477","vol_10410","vol_10413","vol_10604"];
const out = [];
for (const item of items) {
  const j = item.json || {};
  if (targets.includes(j.vorgangKey) && j.nextcloudFolder) {
    out.push({ json: { vorgangKey: j.vorgangKey, vorgangsnummer: j.vorgangsnummer, nextcloudFolder: j.nextcloudFolder, documentCount: j.documentCount, documentsJsonLength: (() => { try { return JSON.parse(j.documentsJson||'[]').length; } catch(e) { return -1; } })() } });
  }
}
return out;

// laeuft als "Run Once For All Items" INNERHALB einer einzelnen Loop-Iteration (batchSize:1),
// daher gehoeren ALLE Input-Items hier garantiert zum selben Vorgang - kein pairedItem-Risiko.
const ziel = $('Loop (1x)').item.json;
const items = $input.all();
const files = items.filter(i => !i.json.error).map(i => ({ name: (i.json.basename || i.json.path || '').split('/').pop(), size: i.json.contentLength || i.json.size || null }));
const errors = items.filter(i => i.json.error).map(i => JSON.stringify(i.json.error).slice(0,200));
return [{ json: {
  vorgangsnummer: ziel.vorgangsnummer,
  vorgangKey: ziel.vorgangKey,
  documentCount_gespeichert: ziel.documentCount,
  documentsJson_length: ziel.documentsJsonLength,
  echte_dateien_gefunden: files.length,
  dateinamen: files.map(f => f.name + ' (' + f.size + 'b)'),
  fehler: errors
} }];
